    async Task RefreshEventStatuses()=> await Exec("UPDATE ExternalEvents SET RegistrationStatus=CASE WHEN RegistrationDeadline IS NOT NULL AND RegistrationDeadline<CONVERT(date,GETDATE()) THEN 'Closed' ELSE 'Open' END,UpdatedAt=CASE WHEN RegistrationStatus<>CASE WHEN RegistrationDeadline IS NOT NULL AND RegistrationDeadline<CONVERT(date,GETDATE()) THEN 'Closed' ELSE 'Open' END THEN SYSUTCDATETIME() ELSE UpdatedAt END");
    public async Task<List<object>> PublicEvents() { await EnsureAsync(); await RefreshEventStatuses(); return await Query("SELECT EventId,EventName,HostingInstitution,EventPortal,RegistrationStatus,Category,Venue,EventFrom,EventTo,RegistrationDeadline,EventType,StudentMessage,MessageSharedAt,RegistrationMode,MinParticipants,MaxParticipants FROM ExternalEvents ORDER BY CreatedAt DESC", r => (object)new { eventId=r.GetInt32(0),eventName=r.GetString(1),hostingInstitution=r.GetString(2),eventPortal=r.IsDBNull(3)?"":r.GetString(3),registrationStatus=r.GetString(4),category=r.IsDBNull(5)?"":r.GetString(5),venue=r.IsDBNull(6)?"":r.GetString(6),eventFrom=r.IsDBNull(7)?(DateTime?)null:r.GetDateTime(7),eventTo=r.IsDBNull(8)?(DateTime?)null:r.GetDateTime(8),registrationDeadline=r.IsDBNull(9)?(DateTime?)null:r.GetDateTime(9),eventType=r.IsDBNull(10)?"":r.GetString(10),studentMessage=r.IsDBNull(11)?"":r.GetString(11),messageSharedAt=r.IsDBNull(12)?(DateTime?)null:r.GetDateTime(12),registrationMode=r.IsDBNull(13)?"Team":r.GetString(13),minParticipants=r.IsDBNull(14)?1:r.GetInt32(14),maxParticipants=r.IsDBNull(15)?10:r.GetInt32(15)}); }
    public async Task<List<object>> Mentors() { await EnsureAsync(); return await Query("SELECT MentorId,MentorName,Designation FROM EventMentors WHERE IsActive=1 ORDER BY MentorName", r => (object)new { mentorId=r.GetInt32(0),mentorName=r.GetString(1),designation=r.GetString(2)}); }
    public async Task<List<object>> PublicTeams() { await EnsureAsync(); return await Query("SELECT t.TeamNumber,e.EventName,t.Category,t.Mentor,t.Status,(SELECT Name,USN,Semester,Branch,Mobile,Email,IsLeader FROM EventTeamMembers m WHERE m.TeamId=t.TeamId ORDER BY IsLeader DESC,MemberId FOR JSON PATH) Members,COALESCE(em.Designation,'Assistant Professor') MentorDesignation FROM EventTeams t JOIN ExternalEvents e ON e.EventId=t.EventId LEFT JOIN EventMentors em ON em.MentorName=t.Mentor WHERE t.TeamNumber IS NOT NULL AND t.ApprovalStatus='Approved' AND t.Status NOT IN ('Rejected','Pending Approval') ORDER BY t.TeamNumber", r => (object)new {teamNumber=r.GetString(0),eventName=r.GetString(1),category=r.GetString(2),mentor=r.IsDBNull(3)?"":r.GetString(3),status=r.GetString(4),members=System.Text.Json.JsonSerializer.Deserialize<object>(r.GetString(5)),mentorDesignation=r.GetString(6)}); }
    public async Task<(string RegistrationReference,string TeamNumber,string Password)> Register(EventRegistrationRequest x)
    {
        await EnsureAsync(); if (!x.DeclarationAccepted || x.Members.Count==0) throw new ArgumentException("Accept the declaration and provide participant details.");
        await RefreshEventStatuses();
        var rules=await Query("SELECT RegistrationStatus,RegistrationMode,MinParticipants,MaxParticipants,EventType FROM ExternalEvents WHERE EventId=@id",r=>(Status:r.GetString(0),Mode:r.GetString(1),Min:r.GetInt32(2),Max:r.GetInt32(3),Type:r.IsDBNull(4)?"":r.GetString(4)),new SqlParameter("@id",x.EventId));
        if(rules.Count==0||rules[0].Status!="Open")throw new ArgumentException("Registration for this event is closed.");
        var rule=rules[0];
        if(x.RegistrationMode is not ("Individual" or "Team"))throw new ArgumentException("Select Individual or Team registration.");
        if(x.RegistrationMode=="Individual"&&x.Members.Count!=1)throw new ArgumentException("Individual registration requires exactly one participant.");
        if(x.RegistrationMode=="Team"&&(x.Members.Count<rule.Min||x.Members.Count>rule.Max))throw new ArgumentException($"This event requires {rule.Min}-{rule.Max} team members.");
        if(x.Members.Count(m=>m.IsLeader)!=1)throw new ArgumentException(x.RegistrationMode=="Individual"?"Select the participant.":"Select exactly one team leader.");
        if(!string.IsNullOrWhiteSpace(x.Mentor)&&Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM EventMentors WHERE MentorName=@m AND IsActive=1",new SqlParameter("@m",x.Mentor.Trim()))??0)==0)throw new ArgumentException("Select a valid faculty mentor/guide.");
        var reference=$"EVR-{DateTime.UtcNow:yyMMdd}-{RandomNumberGenerator.GetInt32(1000,9999)}";
        await using var c=new SqlConnection(cs); await c.OpenAsync(); await using var tx=await c.BeginTransactionAsync();
        var cmd=new SqlCommand("INSERT EventTeams(RegistrationReference,EventId,RegistrationMode,Category,Mentor,DeclarationAccepted) OUTPUT INSERTED.TeamId VALUES(@r,@e,@mode,@c,@m,1)",c,(SqlTransaction)tx); cmd.Parameters.AddRange([new("@r",reference),new("@e",x.EventId),new("@mode",x.RegistrationMode),new("@c",rule.Type),new("@m",string.IsNullOrWhiteSpace(x.Mentor)?DBNull.Value:x.Mentor.Trim())]); var id=(int)(await cmd.ExecuteScalarAsync())!;
        var teamNumber=$"CSE-EVT-{DateTime.Now:yy}-{id:000}";
        var password=$"Atme@{RandomNumberGenerator.GetInt32(100000,999999)}";
        var credentialCipher=credentialProtector.Protect(password);
        var credentials=new SqlCommand("UPDATE EventTeams SET TeamNumber=@n,PasswordHash=@p,CredentialCipher=@x,MustChangePassword=1,Status='Registered',ApprovalStatus='Pending',PostEventStatus='Yet to update' WHERE TeamId=@id",c,(SqlTransaction)tx);
        credentials.Parameters.AddRange([new("@n",teamNumber),new("@p",PasswordSecurity.Hash(password)),new("@x",credentialCipher),new("@id",id)]);await credentials.ExecuteNonQueryAsync();
        foreach(var m in x.Members){ var q=new SqlCommand("INSERT EventTeamMembers(TeamId,Name,USN,Semester,Branch,Mobile,Email,IsLeader) VALUES(@t,@n,@u,@s,@b,@p,@e,@l)",c,(SqlTransaction)tx); q.Parameters.AddRange([new("@t",id),new("@n",m.Name.Trim()),new("@u",m.Usn.Trim().ToUpperInvariant()),new("@s",m.Semester.Trim()),new("@b",m.Branch.Trim()),new("@p",m.Mobile.Trim()),new("@e",m.Email.Trim()),new("@l",m.IsLeader)]); await q.ExecuteNonQueryAsync(); }
        await tx.CommitAsync(); return (reference,teamNumber,password);
    }
    public async Task<EventLoginResponse?> Login(string type,EventLoginRequest x)
    {
        await EnsureAsync(); string sql=type=="Coordinator"?"SELECT CoordinatorId,DisplayName,PasswordHash,MustChangePassword FROM EventCoordinators WHERE Username=@u":"SELECT TeamId,COALESCE(TeamNumber,RegistrationReference),PasswordHash,MustChangePassword FROM EventTeams WHERE TeamNumber=@u";
        await using var c=new SqlConnection(cs); await c.OpenAsync(); await using var cmd=new SqlCommand(sql,c); cmd.Parameters.AddWithValue("@u",x.Username.Trim()); await using var r=await cmd.ExecuteReaderAsync(); if(!await r.ReadAsync()||r.IsDBNull(2)||!PasswordSecurity.Verify(x.Password,r.GetString(2))) return null; var id=r.GetInt32(0); var name=r.GetString(1); var must=r.GetBoolean(3); await r.CloseAsync();
        var token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32)); var exp=DateTime.UtcNow.AddHours(type=="Coordinator"?8:4); await Exec("INSERT EventAuthSessions VALUES(@h,@t,@i,@e,SYSUTCDATETIME())",new("@h",Hash(token)),new("@t",type),new("@i",id),new("@e",exp)); return new(token,type,name,must,exp);
    }
    public async Task<(string Type,int Id)?> Auth(string token){ if(string.IsNullOrWhiteSpace(token))return null; await EnsureAsync(); var rows=await Query("SELECT PrincipalType,PrincipalId FROM EventAuthSessions WHERE TokenHash=@h AND ExpiresAt>SYSUTCDATETIME()",r=>(r.GetString(0),r.GetInt32(1)),new SqlParameter("@h",Hash(token))); return rows.Count==0?null:rows[0]; }
    public async Task<object?> Team(int id,bool includeCredential=false){ var rows=await Query("SELECT t.TeamId,t.RegistrationReference,t.TeamNumber,t.EventId,e.EventName,t.Category,t.Mentor,t.Status,t.ParticipationFrom,t.ParticipationTo,t.PrizeDetails,t.DeclarationAccepted,t.CoordinatorRemarks,COALESCE((SELECT MemberId,Name,USN,Semester,Branch,Mobile,Email,IsLeader FROM EventTeamMembers m WHERE m.TeamId=t.TeamId ORDER BY IsLeader DESC,MemberId FOR JSON PATH),'[]') Members,COALESCE((SELECT FileId,FileType,OriginalName,ContentType,SizeBytes,UploadedAt,Description FROM EventFiles f WHERE f.TeamId=t.TeamId FOR JSON PATH),'[]') Files,t.CreatedAt,e.Venue,e.EventFrom,e.EventTo,e.MessageSharedAt,t.CredentialCipher,t.RegistrationMode,t.ApprovalStatus,t.PostEventStatus,t.NonParticipationReason,e.EventType,(SELECT TOP 1 Designation FROM EventMentors em WHERE em.MentorName=t.Mentor) MentorDesignation,t.ExperienceFeedback FROM EventTeams t JOIN ExternalEvents e ON e.EventId=t.EventId WHERE t.TeamId=@id",r=>(object)new {teamId=r.GetInt32(0),registrationReference=r.IsDBNull(1)?"":r.GetString(1),teamNumber=r.IsDBNull(2)?"":r.GetString(2),eventId=r.GetInt32(3),eventName=r.IsDBNull(4)?"":r.GetString(4),category=r.IsDBNull(5)?"":r.GetString(5),mentor=r.IsDBNull(6)?"":r.GetString(6),status=r.IsDBNull(7)?"":r.GetString(7),participationFrom=r.IsDBNull(8)?(DateTime?)null:r.GetDateTime(8),participationTo=r.IsDBNull(9)?(DateTime?)null:r.GetDateTime(9),prizeDetails=r.IsDBNull(10)?"":r.GetString(10),declarationAccepted=!r.IsDBNull(11)&&r.GetBoolean(11),coordinatorRemarks=r.IsDBNull(12)?"":r.GetString(12),members=System.Text.Json.JsonSerializer.Deserialize<object>(r.IsDBNull(13)?"[]":r.GetString(13)),files=System.Text.Json.JsonSerializer.Deserialize<object>(r.IsDBNull(14)?"[]":r.GetString(14)),registeredAt=r.GetDateTime(15),venue=r.IsDBNull(16)?"":r.GetString(16),eventFrom=r.IsDBNull(17)?(DateTime?)null:r.GetDateTime(17),eventTo=r.IsDBNull(18)?(DateTime?)null:r.GetDateTime(18),messageSharedAt=r.IsDBNull(19)?(DateTime?)null:r.GetDateTime(19),password=includeCredential&&!r.IsDBNull(20)?UnprotectCredential(r.GetString(20)):"",registrationMode=r.IsDBNull(21)?"Team":r.GetString(21),approvalStatus=r.IsDBNull(22)?"Pending":r.GetString(22),postEventStatus=r.IsDBNull(23)?"Yet to update":r.GetString(23),nonParticipationReason=r.IsDBNull(24)?"":r.GetString(24),eventType=r.IsDBNull(25)?"":r.GetString(25),mentorDesignation=r.IsDBNull(26)?"":r.GetString(26),experienceFeedback=r.IsDBNull(27)?"":r.GetString(27)},new SqlParameter("@id",id)); return rows.FirstOrDefault(); }
    public async Task<List<object>> Dashboard(){ await EnsureAsync(); return await Query("SELECT TeamId FROM EventTeams ORDER BY CreatedAt DESC",r=>r.GetInt32(0)).ContinueWith(async t=>{var a=new List<object>();foreach(var id in t.Result){var x=await Team(id,true);if(x!=null)a.Add(x);}return a;}).Unwrap(); }
    public async Task<int> SaveEvent(int? id,ExternalEventRequest x)
    {
        if(x.EventTo.HasValue&&x.EventFrom.HasValue&&x.EventTo.Value.Date<x.EventFrom.Value.Date)throw new ArgumentException("Event end date cannot be before its start date.");
        var status=x.RegistrationDeadline.HasValue&&x.RegistrationDeadline.Value.Date<DateTime.Today?"Closed":"Open";
        if(x.RegistrationMode is not ("Individual" or "Team"))throw new ArgumentException("Registration mode must be Individual or Team.");
        if(x.MinParticipants<1||x.MaxParticipants<x.MinParticipants||x.MaxParticipants>10)throw new ArgumentException("Participant limits must be between 1 and 10.");
        return id is null?await Exec("INSERT ExternalEvents(EventName,HostingInstitution,Venue,EventPortal,RegistrationStatus,Category,EventType,RegistrationMode,MinParticipants,MaxParticipants,StudentMessage,MessageSharedAt,EventFrom,EventTo,RegistrationDeadline) VALUES(@n,@h,@v,@p,@s,@c,@y,@rm,@min,@max,@m,@a,@f,@t,@d)",Params(x,status)):await Exec("UPDATE ExternalEvents SET EventName=@n,HostingInstitution=@h,Venue=@v,EventPortal=@p,RegistrationStatus=@s,Category=@c,EventType=@y,RegistrationMode=@rm,MinParticipants=@min,MaxParticipants=@max,StudentMessage=@m,MessageSharedAt=@a,EventFrom=@f,EventTo=@t,RegistrationDeadline=@d,UpdatedAt=SYSUTCDATETIME() WHERE EventId=@id",[..Params(x,status),new("@id",id)]);
    }
    static SqlParameter[] Params(ExternalEventRequest x,string status)=>[new("@n",x.EventName),new("@h",x.HostingInstitution),new("@v",x.Venue??""),new("@p",x.EventPortal??""),new("@s",status),new("@c",x.Category??"External"),new("@y",x.EventType??""),new("@rm",x.RegistrationMode),new("@min",x.MinParticipants),new("@max",x.MaxParticipants),new("@m",x.StudentMessage??""),new("@a",(object?)x.MessageSharedAt??DBNull.Value),new("@f",(object?)x.EventFrom?.Date??DBNull.Value),new("@t",(object?)x.EventTo?.Date??DBNull.Value),new("@d",(object?)x.RegistrationDeadline?.Date??DBNull.Value)];
    public async Task<List<object>> MentorAllocations(){await EnsureAsync();return await Query("SELECT m.MentorId,m.MentorName,m.Designation,COUNT(t.TeamId) TeamsAllocated FROM EventMentors m LEFT JOIN EventTeams t ON t.Mentor=m.MentorName AND t.Status NOT IN ('Pending Approval','Rejected') GROUP BY m.MentorId,m.MentorName,m.Designation,m.IsActive HAVING m.IsActive=1 OR COUNT(t.TeamId)>0 ORDER BY m.MentorName",r=>(object)new{mentorId=r.GetInt32(0),mentorName=r.GetString(1),designation=r.GetString(2),teamsAllocated=r.GetInt32(3)});}
    public async Task<(string TeamNumber,string Password)> Approve(int id){ var number=$"CSE-EVT-{DateTime.UtcNow:yy}-{id:000}"; var password=$"Atme@{RandomNumberGenerator.GetInt32(100000,999999)}"; await Exec("UPDATE EventTeams SET TeamNumber=COALESCE(TeamNumber,@n),PasswordHash=@p,CredentialCipher=@x,MustChangePassword=1,Status='Registered',UpdatedAt=SYSUTCDATETIME() WHERE TeamId=@id",new("@n",number),new("@p",PasswordSecurity.Hash(password)),new("@x",credentialProtector.Protect(password)),new("@id",id)); return(number,password); }
    public Task<int> Review(int id,TeamReviewRequest x)=>Exec("UPDATE EventTeams SET Status=@s,CoordinatorRemarks=@r,VerifiedAt=CASE WHEN @s='Verified' THEN SYSUTCDATETIME() ELSE VerifiedAt END,UpdatedAt=SYSUTCDATETIME() WHERE TeamId=@id",new("@s",x.Status),new("@r",x.Remarks??""),new("@id",id));
    public async Task UpdateTeam(int id,CoordinatorTeamUpdateRequest x){if(x.Members.Count==0||x.Members.Count>10||x.Members.Count(m=>m.IsLeader)!=1)throw new ArgumentException("A team requires 1-10 members and exactly one leader.");if(x.ApprovalStatus is not ("Pending" or "Approved" or "Not Approved"))throw new ArgumentException("Invalid approval status.");var mentor=x.ApprovalStatus=="Approved"?x.Mentor:"";if(x.ApprovalStatus=="Approved"&&string.IsNullOrWhiteSpace(mentor))throw new ArgumentException("Allocate a mentor before approving the registration.");await using var c=new SqlConnection(cs);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();var q=new SqlCommand("UPDATE EventTeams SET EventId=@e,Category=@c,Mentor=@m,ApprovalStatus=@a,CoordinatorRemarks=@r,UpdatedAt=SYSUTCDATETIME() WHERE TeamId=@id",c,(SqlTransaction)tx);q.Parameters.AddRange([new("@e",x.EventId),new("@c",x.Category),new("@m",mentor),new("@a",x.ApprovalStatus),new("@r",x.Remarks??""),new("@id",id)]);await q.ExecuteNonQueryAsync();q=new SqlCommand("DELETE FROM EventTeamMembers WHERE TeamId=@id",c,(SqlTransaction)tx);q.Parameters.AddWithValue("@id",id);await q.ExecuteNonQueryAsync();foreach(var m in x.Members){q=new SqlCommand("INSERT EventTeamMembers(TeamId,Name,USN,Semester,Branch,Mobile,Email,IsLeader) VALUES(@t,@n,@u,@s,@b,@p,@e,@l)",c,(SqlTransaction)tx);q.Parameters.AddRange([new("@t",id),new("@n",m.Name),new("@u",m.Usn),new("@s",m.Semester),new("@b",m.Branch),new("@p",m.Mobile),new("@e",m.Email),new("@l",m.IsLeader)]);await q.ExecuteNonQueryAsync();}await tx.CommitAsync();}
    public async Task<int> Participation(int id,TeamParticipationRequest x){var allowed=new[]{"Participated","Not Participated","Participated and Won the Competition"};if(!allowed.Contains(x.PostEventStatus))throw new ArgumentException("Select a valid post-event status.");if(!x.DeclarationAccepted)throw new ArgumentException("Accept the declaration before submitting.");if(x.PostEventStatus=="Not Participated"&&string.IsNullOrWhiteSpace(x.NonParticipationReason))throw new ArgumentException("Provide the reason for not participating.");if(x.Members is null||x.Members.Count==0||x.Members.Count>10||x.Members.Count(m=>m.IsLeader)!=1)throw new ArgumentException("Student/Team details require 1-10 members and exactly one team leader.");if(x.Members.Any(m=>string.IsNullOrWhiteSpace(m.Name)||string.IsNullOrWhiteSpace(m.Usn)||string.IsNullOrWhiteSpace(m.Mobile)||string.IsNullOrWhiteSpace(m.Email)))throw new ArgumentException("Name, USN, contact number and email are required for every participant.");if(x.PostEventStatus!="Not Participated"&&(!x.FromDate.HasValue||!x.ToDate.HasValue))throw new ArgumentException("Participation dates are required.");if(x.FromDate.HasValue&&x.ToDate.HasValue&&x.ToDate.Value.Date<x.FromDate.Value.Date)throw new ArgumentException("To date cannot be before from date.");if(x.PostEventStatus=="Participated and Won the Competition"){if(string.IsNullOrWhiteSpace(x.PrizeDetails))throw new ArgumentException("Prize details are required for a winning Student/Team.");var evidence=await Query("SELECT FileType,COUNT(*) FROM EventFiles WHERE TeamId=@id GROUP BY FileType",r=>(Type:r.GetString(0),Count:r.GetInt32(1)),new SqlParameter("@id",id));if(!evidence.Any(e=>e.Type=="Certificate")||!evidence.Any(e=>e.Type=="Photo"))throw new ArgumentException("Upload at least one certificate PDF and one participation photo before submitting a winning result.");}await using var c=new SqlConnection(cs);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();var q=new SqlCommand("DELETE FROM EventTeamMembers WHERE TeamId=@id",c,(SqlTransaction)tx);q.Parameters.AddWithValue("@id",id);await q.ExecuteNonQueryAsync();foreach(var m in x.Members){q=new SqlCommand("INSERT EventTeamMembers(TeamId,Name,USN,Semester,Branch,Mobile,Email,IsLeader) VALUES(@t,@n,@u,@s,@b,@p,@e,@l)",c,(SqlTransaction)tx);q.Parameters.AddRange([new("@t",id),new("@n",m.Name.Trim()),new("@u",m.Usn.Trim()),new("@s",m.Semester?.Trim()??""),new("@b",m.Branch?.Trim()??""),new("@p",m.Mobile.Trim()),new("@e",m.Email.Trim()),new("@l",m.IsLeader)]);await q.ExecuteNonQueryAsync();}var status=x.PostEventStatus=="Participated and Won the Competition"?"Won the Competition":x.PostEventStatus;q=new SqlCommand("UPDATE EventTeams SET ParticipationFrom=@f,ParticipationTo=@to,PrizeDetails=@p,NonParticipationReason=@reason,ExperienceFeedback=@feedback,DeclarationAccepted=@d,PostEventStatus=@post,Status=@s,SubmittedForVerificationAt=SYSUTCDATETIME(),UpdatedAt=SYSUTCDATETIME() WHERE TeamId=@id",c,(SqlTransaction)tx);q.Parameters.AddRange([new("@f",(object?)x.FromDate?.Date??DBNull.Value),new("@to",(object?)x.ToDate?.Date??DBNull.Value),new("@p",x.PrizeDetails??""),new("@reason",x.NonParticipationReason??""),new("@feedback",x.ExperienceFeedback??""),new("@d",x.DeclarationAccepted),new("@post",x.PostEventStatus),new("@s",status),new("@id",id)]);var changed=await q.ExecuteNonQueryAsync();await tx.CommitAsync();return changed;}
    public async Task UpdateOwnDetails(int id,List<EventMemberRequest> members){if(members is null||members.Count==0||members.Count>10||members.Count(m=>m.IsLeader)!=1)throw new ArgumentException("Student/Team details require 1-10 members and exactly one team leader.");if(members.Any(m=>string.IsNullOrWhiteSpace(m.Name)||string.IsNullOrWhiteSpace(m.Usn)||string.IsNullOrWhiteSpace(m.Mobile)||string.IsNullOrWhiteSpace(m.Email)))throw new ArgumentException("Name, USN, contact number and email are required for every participant.");await using var c=new SqlConnection(cs);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();var q=new SqlCommand("DELETE FROM EventTeamMembers WHERE TeamId=@id",c,(SqlTransaction)tx);q.Parameters.AddWithValue("@id",id);await q.ExecuteNonQueryAsync();foreach(var m in members){q=new SqlCommand("INSERT EventTeamMembers(TeamId,Name,USN,Semester,Branch,Mobile,Email,IsLeader) VALUES(@t,@n,@u,@s,@b,@p,@e,@l)",c,(SqlTransaction)tx);q.Parameters.AddRange([new("@t",id),new("@n",m.Name.Trim()),new("@u",m.Usn.Trim()),new("@s",m.Semester?.Trim()??""),new("@b",m.Branch?.Trim()??""),new("@p",m.Mobile.Trim()),new("@e",m.Email.Trim()),new("@l",m.IsLeader)]);await q.ExecuteNonQueryAsync();}q=new SqlCommand("UPDATE EventTeams SET UpdatedAt=SYSUTCDATETIME() WHERE TeamId=@id",c,(SqlTransaction)tx);q.Parameters.AddWithValue("@id",id);await q.ExecuteNonQueryAsync();await tx.CommitAsync();}
    public async Task ChangePassword(int id,string old,string next){var h=(string?)await Scalar("SELECT PasswordHash FROM EventTeams WHERE TeamId=@id",new SqlParameter("@id",id));if(!PasswordSecurity.Verify(old,h)||next.Length<8)throw new ArgumentException("Current password is incorrect or new password is too short.");await Exec("UPDATE EventTeams SET PasswordHash=@p,CredentialCipher=@x,MustChangePassword=0 WHERE TeamId=@id",new SqlParameter("@p",PasswordSecurity.Hash(next)),new SqlParameter("@x",credentialProtector.Protect(next)),new SqlParameter("@id",id));}
    public async Task<object> SaveFile(int teamId,string type,string description,IFormFile file){if(string.IsNullOrWhiteSpace(description))throw new ArgumentException("Describe the file before uploading it.");var allowed=type=="Certificate"&&file.ContentType=="application/pdf"&&file.Length<=10_000_000||type=="Photo"&&new[]{"image/jpeg","image/png","image/webp"}.Contains(file.ContentType)&&file.Length<=5_000_000;if(!allowed)throw new ArgumentException("Invalid file type or size.");var count=Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM EventFiles WHERE TeamId=@t AND FileType=@y",new SqlParameter("@t",teamId),new SqlParameter("@y",type))??0);if(count>=10)throw new ArgumentException($"A maximum of ten {(type=="Certificate"?"certificate PDFs":"photos")} is allowed.");await using var memory=new MemoryStream();await file.CopyToAsync(memory);var id=Guid.NewGuid();await Exec("INSERT EventFiles(FileId,TeamId,FileType,OriginalName,ContentType,SizeBytes,FileData,Description) VALUES(@id,@t,@y,@o,@c,@z,@d,@desc)",new SqlParameter("@id",id),new SqlParameter("@t",teamId),new SqlParameter("@y",type),new SqlParameter("@o",Path.GetFileName(file.FileName)),new SqlParameter("@c",file.ContentType),new SqlParameter("@z",file.Length),new SqlParameter("@d",SqlDbType.VarBinary,-1){Value=memory.ToArray()},new SqlParameter("@desc",description.Trim()));return new{fileId=id,fileType=type,fileName=file.FileName,description=description.Trim()};}
    public async Task<(byte[] Data,string Name,string ContentType)?> File(Guid id,int principalId,bool coordinator){var sql=coordinator?"SELECT FileData,OriginalName,ContentType FROM EventFiles WHERE FileId=@id":"SELECT FileData,OriginalName,ContentType FROM EventFiles WHERE FileId=@id AND TeamId=@t";var rows=await Query(sql,r=>((byte[])r[0],r.GetString(1),r.GetString(2)),new SqlParameter("@id",id),new SqlParameter("@t",principalId));return rows.Count==0?null:rows[0];}
    static string Hash(string x)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(x)));
    string UnprotectCredential(string value){try{return credentialProtector.Unprotect(value);}catch{return "Password unavailable - reset required";}}
    async Task EnsureMissingTeamCredentials(){var ids=await Query("SELECT TeamId FROM EventTeams WHERE TeamNumber IS NOT NULL AND PasswordHash IS NULL",r=>r.GetInt32(0));foreach(var id in ids){var password=$"Atme@{RandomNumberGenerator.GetInt32(100000,999999)}";await Exec("UPDATE EventTeams SET PasswordHash=@p,CredentialCipher=@x,MustChangePassword=1 WHERE TeamId=@id",new("@p",PasswordSecurity.Hash(password)),new("@x",credentialProtector.Protect(password)),new("@id",id));}}
    async Task<int> Exec(string sql,params SqlParameter[] p){await using var c=new SqlConnection(cs);await c.OpenAsync();await using var q=new SqlCommand(sql,c);q.Parameters.AddRange(p);return await q.ExecuteNonQueryAsync();}
    async Task<object?> Scalar(string sql,params SqlParameter[] p){await using var c=new SqlConnection(cs);await c.OpenAsync();await using var q=new SqlCommand(sql,c);q.Parameters.AddRange(p);return await q.ExecuteScalarAsync();}
    async Task<List<T>> Query<T>(string sql,Func<SqlDataReader,T> map,params SqlParameter[] p){var x=new List<T>();await using var c=new SqlConnection(cs);await c.OpenAsync();await using var q=new SqlCommand(sql,c);q.Parameters.AddRange(p.Where(z=>z.ParameterName!="@t"||sql.Contains("@t")).ToArray());await using var r=await q.ExecuteReaderAsync();while(await r.ReadAsync())x.Add(map(r));return x;}
